    const p = configSchema.parse(raw),
      endpoint = new URL(p.endpoint);
    if (
      endpoint.username ||
      endpoint.password ||
      !["https:", "http:"].includes(endpoint.protocol) ||
      (endpoint.protocol === "http:" && !p.allowInsecure)
