        ).run(p.extensionId, p.key, value);
        return true;
      });
    }

if (op === "extensionDeleteState")
      result = s.tx(db, p.extensionId, "extension", () => {
        db.prepare(
          "DELETE FROM extension_data WHERE extension_id=? AND key=?",
        ).run(p.extensionId, p.key);
        return true;
